example_item.example_item_data:
schema = protobuf.load([modulepath('protobuf'), '/tests/data/sensor_stream.proto']);
bytes = protobuf.encode(schema, 'SensorSample', struct('timestamp_ms', 1000, 'status', 1));
protobuf.decode(schema, 'SensorSample', bytes)

schema = protobuf.load([modulepath('protobuf'), '/tests/data/sensor_stream.proto']);
records = struct('timestamp_ms', {1000, 1040, 1080}, 'pressure', {single(5.2), [], single(5.6)});
filename = [tempdir(), 'samples.bin'];
protobuf.write(schema, 'SensorSample', filename, records, 'Delimited', true);
[C, present] = protobuf.read(schema, 'SensorSample', filename, 'Delimited', true, 'Layout', 'columns');
C.pressure
present.pressure
delete(filename);
